// 在画布上拖拽控制点：按下时选中 14px 内最近的点，拖动时更新坐标
const useDraggablePoints = (canvasRef, points, setPoints) => {
  const activeRef = useRef(-1);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const locate = event => {
      const rect = canvas.getBoundingClientRect();
      return { x: event.clientX - rect.left, y: event.clientY - rect.top, rect };
    };
    const down = event => {
      const { x, y } = locate(event);
      const index = points.findIndex(point => Math.hypot(point.x - x, point.y - y) < 14);
      if (index < 0) return;
      activeRef.current = index;
      canvas.setPointerCapture(event.pointerId);
    };
    const move = event => {
      const { x, y, rect } = locate(event);
      const hovering = points.some(point => Math.hypot(point.x - x, point.y - y) < 14);
      canvas.style.cursor = activeRef.current >= 0 ? "grabbing" : hovering ? "grab" : "";
      if (activeRef.current < 0) return;
      const clamp = (value, max) => Math.min(Math.max(value, 6), max - 6);
      const next = { x: clamp(x, rect.width), y: clamp(y, rect.height) };
      setPoints(list => list.map((point, index) => (index === activeRef.current ? { ...point, ...next } : point)));
    };
    const up = () => {
      activeRef.current = -1;
    };
    canvas.addEventListener("pointerdown", down);
    canvas.addEventListener("pointermove", move);
    canvas.addEventListener("pointerup", up);
    canvas.addEventListener("pointercancel", up);
    return () => {
      canvas.removeEventListener("pointerdown", down);
      canvas.removeEventListener("pointermove", move);
      canvas.removeEventListener("pointerup", up);
      canvas.removeEventListener("pointercancel", up);
    };
  }, [points]);
};

// 控制点：实心圆点加名称
const handle = (ctx, color, point, name, token = "accent") => {
  ctx.save();
  ctx.fillStyle = color("bg-surface");
  ctx.strokeStyle = color(token);
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(point.x, point.y, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.restore();
  note(ctx, color, name, point.x + 10, point.y - 10);
};

const Component = () => {
  const [points, setPoints] = useState([
    { x: 60, y: 60 },
    { x: 260, y: 60 },
    { x: 320, y: 220 },
  ]);
  const [radius, setRadius] = useState(80);
  const ref = useCanvas((ctx, { color }) => {
    const [start, p1, p2] = points;
    // 两条切线：start→p1、p1→p2
    ctx.save();
    ctx.setLineDash([6, 5]);
    ctx.strokeStyle = color("line-1");
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(start.x, start.y);
    ctx.lineTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.stroke();
    ctx.restore();
    ctx.beginPath();
    ctx.lineWidth = 3;
    ctx.strokeStyle = color("accent");
    ctx.moveTo(start.x, start.y);
    ctx.arcTo(p1.x, p1.y, p2.x, p2.y, radius);
    ctx.stroke();
    handle(ctx, color, start, "起点", "tag-1");
    handle(ctx, color, p1, "(x1, y1)", "tag-2");
    handle(ctx, color, p2, "(x2, y2)", "tag-3");
  }, [points, radius]);
  useDraggablePoints(ref, points, setPoints);

  return (
    <Demo>
      <Stage canvasRef={ref} height={260} className="touch-none" />
      <Row>
        <Slider label="r" value={radius} min={10} max={160} onChange={setRadius} format={value => `${value}px`} />
        <span className="text-tau-meta text-ink-3">拖动三个点改变切线</span>
      </Row>
    </Demo>
  );
};
